<?php use App\Helpers\ViewHelper; $filters = $filters ?? ['category'=>'','author'=>'','min_price'=>null,'max_price'=>null,'sort'=>'newest']; $field = 'block min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 outline-none focus:border-blue-700 focus:ring-4 focus:ring-blue-100'; $button = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-3.5 py-2 text-sm font-semibold transition focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-100'; ?>
<div class="mx-auto max-w-[1240px] px-4 pb-16 pt-8 sm:px-6 lg:px-8"><?php require dirname(__DIR__) . '/partials/breadcrumbs.php'; ?><header class="mt-6 border-b border-slate-200 pb-7"><p class="text-[11px] font-bold uppercase tracking-[0.18em] text-orange-600">Bộ sưu tập</p><h1 class="mt-2 text-3xl font-bold tracking-tight text-slate-950">Tất cả sách</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Tìm sách theo danh mục, tác giả, khoảng giá và thứ tự hiển thị.</p></header><section class="mt-7"><form class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6" method="get" action="/books"><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><label class="text-sm font-semibold text-slate-700">Danh mục<select class="<?= $field ?> mt-2" id="filter-category" name="category"><option value="">Tất cả danh mục</option><?php foreach ($categories ?? [] as $category): ?><option value="<?= ViewHelper::escape($category['slug']) ?>" <?= ($filters['category'] ?? '') === $category['slug'] ? 'selected' : '' ?>><?= ViewHelper::escape($category['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold text-slate-700">Tác giả<select class="<?= $field ?> mt-2" id="filter-author" name="author"><option value="">Tất cả tác giả</option><?php foreach ($authors ?? [] as $author): ?><option value="<?= ViewHelper::escape($author) ?>" <?= ($filters['author'] ?? '') === $author ? 'selected' : '' ?>><?= ViewHelper::escape($author) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold text-slate-700">Giá từ<input class="<?= $field ?> mt-2" id="filter-min-price" name="min_price" type="number" min="0" step="1000" value="<?= $filters['min_price'] !== null ? (int)$filters['min_price'] : '' ?>" placeholder="VNĐ"></label><label class="text-sm font-semibold text-slate-700">Giá đến<input class="<?= $field ?> mt-2" id="filter-max-price" name="max_price" type="number" min="0" step="1000" value="<?= $filters['max_price'] !== null ? (int)$filters['max_price'] : '' ?>" placeholder="VNĐ"></label><label class="text-sm font-semibold text-slate-700">Sắp xếp<select class="<?= $field ?> mt-2" id="filter-sort" name="sort"><option value="newest" <?= ($filters['sort'] ?? '') === 'newest' ? 'selected' : '' ?>>Mới nhất</option><option value="price_asc" <?= ($filters['sort'] ?? '') === 'price_asc' ? 'selected' : '' ?>>Giá thấp đến cao</option><option value="price_desc" <?= ($filters['sort'] ?? '') === 'price_desc' ? 'selected' : '' ?>>Giá cao đến thấp</option></select></label></div><div class="mt-5 flex flex-wrap gap-3"><button class="<?= $button ?> bg-orange-700 text-white hover:bg-orange-800" type="submit"><span class="material-symbols-outlined text-[18px]" aria-hidden="true">filter_alt</span>Lọc sách</button><a class="<?= $button ?> border border-slate-300 bg-white text-slate-700 hover:bg-slate-50" href="/books">Xóa lọc</a></div></form><p class="my-5 text-sm text-slate-500">Có <strong class="text-slate-900"><?= count($books) ?></strong> sách phù hợp.</p><?php if ($books): ?><div class="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5"><?php foreach ($books as $book): ?><?php require dirname(__DIR__) . '/partials/book_card.php'; ?><?php endforeach; ?></div><?php else: ?><div class="rounded-2xl border border-slate-200 bg-white p-8 text-center shadow-sm"><span class="mx-auto flex size-12 items-center justify-center rounded-xl bg-slate-100 text-slate-500"><span class="material-symbols-outlined" aria-hidden="true">search_off</span></span><h2 class="mt-4 text-xl font-bold text-slate-950">Không tìm thấy sách phù hợp</h2><p class="mt-1 text-sm text-slate-500">Hãy thử nới rộng điều kiện lọc.</p><a class="<?= $button ?> mt-5 bg-orange-700 text-white hover:bg-orange-800" href="/books">Xem toàn bộ sách</a></div><?php endif; ?></section></div>